/**
 * Landlord referral commission accrual.
 *
 * Business rule: a landlord referral commission is NOT a one-off payment.
 * The referrer earns 10% of the agency management fee generated by that
 * landlord's properties EVERY MONTH, for the duration of the management
 * contract (landlord.contractPeriod, in months, starting from the landlord's
 * join / contract start date). When no contract period is recorded the
 * commission keeps accruing for as long as the landlord is managed.
 */

export const REFERRER_SHARE = 0.1;

export type LandlordCommissionMonth = {
    period: string; // YYYY-MM
    collected: number;
    expected: number;
    agencyFee: number;
    commission: number;
};

export type LandlordCommissionAccrual = {
    contractStart: string; // YYYY-MM
    contractEndPeriod: string | null; // YYYY-MM inclusive, null = ongoing
    contractPeriodMonths: number | null;
    monthsAccrued: number;
    monthsRemaining: number | null;
    months: LandlordCommissionMonth[];
    currentMonthCommission: number;
    totalCommission: number;
    expectedCollection: number;
    collectionMTD: number;
    agencyFeeMTD: number;
    isExpired: boolean;
};

const toPeriod = (d: Date): string => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;

const addMonthsToPeriod = (period: string, months: number): string => {
    const [y, m] = period.split('-').map(Number);
    const d = new Date(y, (m - 1) + months, 1);
    return toPeriod(d);
};

const periodRange = (start: string, end: string): string[] => {
    const out: string[] = [];
    let cur = start;
    let guard = 0;
    while (cur <= end && guard < 600) {
        out.push(cur);
        cur = addMonthsToPeriod(cur, 1);
        guard += 1;
    }
    return out;
};

const num = (v: any): number => parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0;
const norm = (v: any): string => String(v || '').trim().toLowerCase();

const OCCUPIED_STATUSES = ['active', 'pending', 'pendingallocation', 'pendingpayment', 'pendingapproval', 'overdue', 'notice'];

export function computeLandlordReferralAccrual(opts: {
    landlord: any;
    properties: any[];
    tenants: any[];
    currentPeriod: string; // YYYY-MM
}): LandlordCommissionAccrual {
    const { landlord, currentPeriod } = opts;
    const landlordProperties = (opts.properties || []).filter(p => p.landlordId === landlord.id);
    const tenants = opts.tenants || [];

    // --- contract window -------------------------------------------------
    const rawStart = landlord.contractStartDate || landlord.managementStartDate || landlord.joinDate || '';
    let contractStart = String(rawStart).slice(0, 7);
    if (!/^\d{4}-\d{2}$/.test(contractStart)) {
        // Fall back to the earliest recorded receipt on the landlord's properties.
        const propIds = new Set(landlordProperties.map(p => p.id));
        let earliest = '';
        tenants.forEach(t => {
            if (!propIds.has(t.propertyId)) return;
            (t.paymentHistory || []).forEach((p: any) => {
                const period = String(p?.date || '').slice(0, 7);
                if (/^\d{4}-\d{2}$/.test(period) && (!earliest || period < earliest)) earliest = period;
            });
        });
        contractStart = earliest || currentPeriod;
    }
    if (contractStart > currentPeriod) contractStart = currentPeriod;

    const contractPeriodMonths = Number(landlord.contractPeriod) > 0 ? Number(landlord.contractPeriod) : null;
    const contractEndPeriod = contractPeriodMonths ? addMonthsToPeriod(contractStart, contractPeriodMonths - 1) : null;
    const lastAccrualPeriod = contractEndPeriod && contractEndPeriod < currentPeriod ? contractEndPeriod : currentPeriod;
    const isExpired = !!contractEndPeriod && contractEndPeriod < currentPeriod;

    // --- expected (occupancy snapshot, same for each month) ---------------
    let expectedCollection = 0;
    const propertyExpected = new Map<string, number>();
    landlordProperties.forEach(p => {
        const pTenants = tenants.filter(t => t.propertyId === p.id);
        let unitBased = (p.units || []).reduce((sum: number, u: any) => {
            const rent = pTenants
                .filter(t => OCCUPIED_STATUSES.includes(norm(t.status)) && ((t.unitId && t.unitId === u.id) || (norm(t.unit) && [u.unitNumber, u.unitTag, u.name].some((c: any) => norm(c) === norm(t.unit)))))
                .reduce((mx: number, t: any) => Math.max(mx, Number(t.rentAmount) || 0), 0);
            return sum + rent;
        }, 0);
        if (unitBased === 0) {
            unitBased = pTenants.filter(t => OCCUPIED_STATUSES.includes(norm(t.status))).reduce((s: number, t: any) => s + (Number(t.rentAmount) || 0), 0);
        }
        propertyExpected.set(p.id, unitBased);
        expectedCollection += unitBased;
    });

    const feeForPeriod = (period: string) => {
        let collected = 0;
        let agencyFee = 0;
        landlordProperties.forEach(p => {
            const pTenants = tenants.filter(t => t.propertyId === p.id);
            const propCollected = pTenants.reduce((s: number, t: any) => s + (t.paymentHistory || [])
                .filter((pp: any) => String(pp?.date || '').startsWith(period) && pp.status === 'Paid')
                .reduce((ss: number, pp: any) => ss + num(pp.amount), 0), 0);
            collected += propCollected;
            const expected = propertyExpected.get(p.id) || 0;
            const feeBase = p.remittanceType === 'Occupancy Based' ? expected : propCollected;
            if (p.agencyCommissionType === 'flat' && typeof p.agencyCommissionFlat === 'number') {
                agencyFee += Number(p.agencyCommissionFlat) || 0;
            } else {
                const pct = typeof p.agencyCommissionPercent === 'number' ? p.agencyCommissionPercent : 10;
                agencyFee += feeBase * (pct / 100);
            }
        });
        return { collected, agencyFee };
    };

    const months: LandlordCommissionMonth[] = periodRange(contractStart, lastAccrualPeriod).map(period => {
        const { collected, agencyFee } = feeForPeriod(period);
        return {
            period,
            collected,
            expected: expectedCollection,
            agencyFee,
            commission: Math.round(agencyFee * REFERRER_SHARE),
        };
    });

    const current = months.find(m => m.period === currentPeriod);
    const totalCommission = months.reduce((s, m) => s + m.commission, 0);
    const monthsRemaining = contractPeriodMonths ? Math.max(0, contractPeriodMonths - months.length) : null;

    return {
        contractStart,
        contractEndPeriod,
        contractPeriodMonths,
        monthsAccrued: months.length,
        monthsRemaining,
        months,
        currentMonthCommission: current?.commission || 0,
        totalCommission,
        expectedCollection,
        collectionMTD: current?.collected || 0,
        agencyFeeMTD: current?.agencyFee || 0,
        isExpired,
    };
}
